const categories=new Set(['Doklady','Stripe','Vypisy','Vystavene_FA']);
const date=value=>{const text=String(value||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(text))return '';const parsed=new Date(text+'T00:00:00Z');return !Number.isNaN(parsed.getTime())&&parsed.toISOString().slice(0,10)===text?text:'';};
return $input.all().map((item,index)=>{
  const row=item.json;
  const deliveryDate=date(row.resolvedDeliveryDate);
  const category=String(row.resolvedCategory||'');
  const currency=String(row.resolvedCurrency||'').toUpperCase();
  if(!row.documentId||!row.sourceFileId)throw new Error('Review položke chýba identita dokumentu alebo Drive súboru');
  if(!deliveryDate||!categories.has(category))throw new Error('Review rozhodnutie nemá platný dátum alebo kategóriu');
  if((category==='Doklady'||category==='Vystavene_FA')&&!/^[A-Z]{3}$/.test(currency))throw new Error('Faktúra nemá potvrdenú menu');
  const period=deliveryDate.slice(0,7);
  const targetFolderId=folderMap[period]?.[category]||'';
  if(!targetFolderId)throw new Error('Pre review rozhodnutie neexistuje cieľový priečinok');
  const safe=value=>String(value||'').trim().replace(/[\/:*?"<>|]/g,'-').replace(/[\r\n]/g,' ').slice(0,100);
  const ext=String(row.sourceFileName||'doklad.pdf').match(/\.([a-zA-Z0-9]{1,8})$/)?.[1]?.toLowerCase()||'pdf';
  const fileName=[deliveryDate,safe(row.supplier)||category,safe(row.invoiceNumber)||'bez-cisla',typeof row.totalAmount==='number'?row.totalAmount.toFixed(2):'suma-neznama',currency||'mena-neznama'].join('_').slice(0,180)+'.'+ext;
  return {json:{...row,deliveryDate,category,currency,period,targetFolderId,fileName},pairedItem:{item:index}};
});

const decision=$('Validuj review rozhodnutie').item.json;
const moved=$('Drive — presuň existujúci originál').item.json;
const rows=$json.values||[];
const index=rows.findIndex(row=>String(row?.[0]||'')===String(decision.documentId));
if(index<1)throw new Error('Register neobsahuje Doklad ID '+decision.documentId);
const row=index+1;
const now=new Date().toISOString();
const url='https://drive.google.com/file/d/'+moved.id+'/view';
const data=[
  {range:'Doklady!C'+row,values:[[decision.period]]},
  {range:'Doklady!E'+row,values:[['Zaradené']]},
  {range:'Doklady!H'+row,values:[[decision.deliveryDate]]},
  {range:'Doklady!P'+row,values:[[decision.currency]]},
  {range:'Doklady!W'+row,values:[[moved.id]]},
  {range:'Doklady!X'+row,values:[[url]]},
  {range:'Doklady!AB'+row,values:[['']]},
  {range:'Doklady!AF'+row,values:[[decision.resolutionNote||'Manuálne potvrdené v Macaly']]},
  {range:'Doklady!AH'+row,values:[['sara-review-outbox-v1']]},
  {range:'Doklady!AI'+row,values:[[now]]},
];
return [{json:{documentId:decision.documentId,targetFileId:moved.id,targetFileUrl:url,body:{valueInputOption:'RAW',data}}}];
